insert into public.guia_materias (slug, nome, categoria, resumo, sinonimos, funcao, composicao, inclusao, especies, restricoes, umidade, densidade_kg_m3, forma_fisica, fluidez, empedra, forma_ponte, abrasivo, oleoso, gera_poeira, corrosivo, risco_micotoxina, precisa_moer, granulometria, direto_misturador, exige_pre_mistura, microingrediente, compat_rosca, exige_exaustao, exige_limpeza_rapida, misturador_indicado, afeta_homogeneidade, armazenamento, compat_branorte, compat_motivo, equipamentos, nivel_risco, alerta, perguntas, explicar_cliente, resumo_30s, regiao, imagem_slug, emoji, status, pendente_validacao, pendencias, fontes, autor, revisor_tecnico, revisado_em, proxima_revisao, ordem) values
  ('milho', 'Milho (grão)', 'energetico', 'Grão de milho, base energética da nutrição animal brasileira. Rico em amido.', '{"milho moído","milho triturado","fubá","milho em grão"}'::text[], 'Principal fonte de ENERGIA da ração (amido). Também traz palatabilidade e pigmento (xantofilas) que dá cor à gema e à pele da ave.', 'Referência: ~8% de proteína bruta, pobre em lisina. Energia alta. Valores exatos variam com safra, secagem e origem — conferir na tabela de composição vigente.', '{"aves": "55–70% da ração", "suinos": "55–70% da ração", "bovinos_confinamento": "30–60% do concentrado", "bovinos_leite": "20–40% do concentrado"}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Baixo em proteína e pobre em lisina — sempre exige complemento proteico.","Preço volátil: sozinho dita boa parte do custo da ração."}'::text[], 'Deve entrar com até ~14% para armazenar sem risco. Acima disso, embolora.', '~700–750 kg/m³ em grão inteiro; cai depois de moído.', 'Grão inteiro (precisa moer) ou já moído/triturado.', 'livre', false, false, false, false, true, false, true, true, 'Moagem média. Peneira de 3 a 5 mm cobre a maioria das rações farelada; aves e leitão pedem mais fino, bovino tolera mais grosso.', false, false, false, true, false, false, 'qualquer', false, 'Silo metálico ou sacaria em local seco e ventilado. É o ingrediente que mais justifica silo próprio.', 'ok', 'É o carro-chefe da linha. Moinho de martelo Branorte tritura; chupim e rosca transportam; misturador vertical ou horizontal homogeneíza. A linha Compacta foi desenhada em torno dele.', '{"MOINHO","SILO","TRANSPORTADOR","MISTURADOR","PRE_LIMPEZA","ENSACADEIRA"}'::text[], 'atencao', 'Risco de MICOTOXINAS (aflatoxina, fumonisina) em grão úmido ou mal armazenado. Milho embolorado não se recupera com moagem — contamina o lote inteiro.', '{"Compra milho em grão ou já moído?","Tem secador ou compra seco?","Quantos sacos/toneladas por mês?","Onde guarda hoje — silo, barracão, sacaria?","Já teve problema de mofo ou de bicho no milho?"}'::text[], 'O milho é a gasolina da ração — é o que dá energia pro animal crescer, engordar ou produzir leite. Se o senhor já colhe ou compra milho, moer aqui na propriedade tira o custo da moagem de terceiro e o frete da ração pronta.', 'Fonte nº 1 de energia, 55–70% da ração de aves e suínos. Precisa moer e precisa de complemento proteico. Cuidado com umidade e micotoxina.', 'Todo o Brasil. Mais barato no Centro-Oeste (MT, GO, MS) e Sul (PR, RS). No Nordeste sai mais caro por depender de frete do Centro-Sul.', 'milho', '🌽', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 10),
  ('sorgo', 'Sorgo (grão)', 'energetico', 'Grão energético semelhante ao milho, usado para baratear a ração quando o milho sobe.', '{"sorgo granífero"}'::text[], 'Fonte de ENERGIA (amido), substituto direto do milho.', 'Referência: energia próxima à do milho (a literatura costuma citar 90–95%). Sem os pigmentos amarelos do milho.', '{"geral": "Pode substituir boa parte do milho; o limite depende do teor de taninos da variedade. Faixa exata a definir com o nutricionista."}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Variedades de grão escuro têm mais TANINO, que reduz digestibilidade e palatabilidade — preferir baixo tanino.","Sem pigmento: gema e pele do frango ficam mais pálidas, o que pesa em quem vende ovo/frango pela cor."}'::text[], 'Mesma exigência do milho: até ~14% para armazenar.', '~720–780 kg/m³ — um pouco mais denso que o milho.', 'Grão pequeno e duro.', 'livre', false, false, true, false, true, false, true, true, 'Grão menor e mais duro que o milho: exige peneira mais fina e desgasta martelo e peneira um pouco mais rápido.', false, null, null, true, false, null, 'qualquer', false, 'Silo ou sacaria seca, igual ao milho.', 'ok', 'Mesma linha do milho. Avisar o cliente que o desgaste de martelo e peneira é maior que com milho — vale conversar sobre peça de reposição.', '{"MOINHO","SILO","TRANSPORTADOR","MISTURADOR","ACESSORIO"}'::text[], 'atencao', 'Confirmar se o sorgo é de baixo tanino ANTES de dimensionar a fórmula em cima dele.', '{"O sorgo é de baixo tanino? Sabe a variedade?","É safrinha própria ou comprado?","Está substituindo milho por preço ou por disponibilidade?"}'::text[], 'O sorgo faz quase o mesmo trabalho do milho e costuma custar menos. Só muda a cor da gema e do frango, e o grão é mais duro — desgasta um pouco mais o martelo do moinho.', 'Substituto do milho. Energia parecida, preço menor, sem pigmento. Grão duro: mais desgaste de martelo e peneira.', 'Forte no Centro-Oeste (safrinha em MT e GO) e crescendo no Nordeste (BA, PI) por tolerar seca.', 'sorgo', '🌾', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 20),
  ('raspa-mandioca', 'Raspa de mandioca', 'energetico', 'Raiz de mandioca triturada e seca. Alternativa energética regional ao milho.', '{"raspa integral","raspa de macaxeira","raspa de aipim"}'::text[], 'Fonte de ENERGIA (amido) barata onde há mandioca.', 'Referência: praticamente sem proteína (~2–3%). Energia depende muito da secagem.', '{"bovinos": "Substitui parte do milho no concentrado.", "aves_suinos": "Uso moderado. Faixa a definir com o nutricionista."}'::jsonb, '{"bovinos","suinos","aves","ovinos","caprinos"}'::text[], '{"Quase sem proteína — exige complemento proteico forte.","Raspa mal seca retém ácido cianídrico residual e umidade que embolora."}'::text[], 'CRÍTICO. Raspa mal seca é o defeito mais comum: emboloramento e HCN residual.', 'Baixa — ocupa mais volume por quilo que o milho.', 'Lascas secas e pó.', 'media', true, true, false, false, true, false, true, true, 'Precisa quebrar a lasca. Gera muito fino no processo.', false, null, null, true, true, null, 'qualquer', false, 'Local MUITO seco. É o ingrediente da lista que mais sofre com umidade de galpão.', 'ressalva', 'Processa na linha, mas gera bastante pó fino e tem tendência a formar ponte em caixa e silo. Vale conversar sobre exaustão no ponto de moagem e sobre o formato da caixa de recepção.', '{"MOINHO","MISTURADOR","CAIXA","TRANSPORTADOR"}'::text[], 'atencao', 'Poeira fina em volume: sem exaustão, incomoda o operador e suja o galpão. Conferir a secagem antes de fechar a fórmula.', '{"A raspa é da propriedade ou comprada?","Como é feita a secagem?","Já teve problema de mofo?","Onde vai armazenar?"}'::text[], 'Onde tem mandioca, a raspa substitui parte do milho e sai bem mais barata. Só que ela quase não tem proteína, então precisa reforçar o farelo, e ela faz mais pó que o milho.', 'Energia barata onde há mandioca. Quase sem proteína. Faz pó e forma ponte — atenção à secagem e à exaustão.', 'Nordeste (BA, Alagoas, sertão), Norte e Paraná (polo de fécula).', 'raspa-mandioca', '🌱', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 30),
  ('oleo-gordura', 'Óleo / Gordura (vegetal ou animal)', 'liquido', 'Óleo de soja, óleo ou gordura de aves, sebo bovino, gordura protegida. Ingrediente LÍQUIDO.', '{"óleo de soja","sebo","gordura protegida","óleo vegetal"}'::text[], 'Fonte CONCENTRADA de energia — mais que o dobro da energia do amido por grama. Aumenta a densidade calórica, dá palatabilidade, reduz poeira da ração e carrega vitaminas lipossolúveis.', 'Energia muito alta. Composição varia com a origem (vegetal x animal) e com o grau de proteção.', '{"aves_suinos": "1–5% da ração (referência)", "bovinos": "Gordura TOTAL da dieta costuma ser limitada a ~6–7% da matéria seca."}'::jsonb, '{"aves","suinos","bovinos"}'::text[], '{"Óleo livre em excesso no ruminante prejudica a digestão da fibra no rúmen — usar gordura protegida.","Rancifica com o tempo: exige antioxidante e rotatividade de estoque.","Custo alto por quilo."}'::text[], 'n/a — é líquido.', '~900–930 kg/m³ (líquido).', 'Líquido (ou gordura pastosa/sólida à temperatura ambiente, no caso do sebo).', 'nao_flui', false, false, false, true, false, false, false, false, null, false, true, null, false, false, true, 'horizontal', true, 'Tambor ou tanque. Sebo pode precisar de aquecimento pra bombear.', 'incompativel', 'A linha Compacta padrão é para produto SECO e não inclui sistema de dosagem e aspersão de líquido. Sem bico aspersor e bomba dosadora, o óleo empelota, adere à rosca e ao helicoide e compromete a homogeneidade. NÃO prometer inclusão de óleo sem antes avaliar sistema específico com a engenharia.', '{}'::text[], 'incompativel', 'NÃO considerar compatível automaticamente. Exige sistema de dosagem e pulverização, tem limite técnico de percentual e cria rotina de limpeza pesada (o resíduo oleoso não sai a seco). Antes de qualquer promessa, levar à engenharia.', '{"O cliente já usa óleo na fórmula hoje? Em que percentual?","Como ele adiciona hoje — na mão, no cocho, ou tem dosador?","É óleo livre ou gordura protegida?","Ele aceitaria manter o óleo fora da fábrica e adicionar no trato?"}'::text[], 'Óleo dá muita energia, mas é líquido — e a nossa fábrica é para produto seco. Se o senhor precisa de óleo na fórmula, isso exige um sistema separado de dosagem. É melhor a gente avaliar isso antes, do que eu prometer uma coisa que a máquina não faz.', 'Energia concentrada, mas LÍQUIDO. Fora do escopo da Compacta padrão. Exige sistema de dosagem/aspersão — levar à engenharia antes de prometer.', 'Óleo de soja abundante nas esmagadoras (Sul e Centro-Oeste); gorduras animais via frigoríficos.', 'oleo-soja', '🛢️', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Confirmar com a engenharia se existe solução Branorte de dosagem de líquido e em que capacidade."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 40),
  ('farelo-soja', 'Farelo de soja', 'proteico', 'Coproduto da extração do óleo de soja, moído. A principal fonte de proteína vegetal do país.', '{"farelo de soja 46","soja farelo"}'::text[], 'Principal fonte de PROTEÍNA e de aminoácidos (lisina). Forma com o milho a dupla que sustenta quase toda ração de monogástrico.', 'Referência: 44–48% de proteína bruta, conforme o processamento.', '{"aves": "15–35% da ração", "suinos": "15–35% da ração", "bovinos": "5–20% do concentrado"}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Soja crua ou mal tostada tem fatores antinutricionais (inibidores de tripsina) que atrapalham a digestão — exige processamento adequado.","Depois do milho, costuma ser o item mais caro da fórmula."}'::text[], 'Farelo comercial vem seco. Absorve umidade do ambiente.', '~600–650 kg/m³.', 'Farelo, já na granulometria de uso.', 'media', true, true, false, false, true, false, true, false, 'Chega pronto. Só precisa moer se vier em pellet/torta.', true, false, false, true, false, null, 'qualquer', false, 'Sacaria ou big bag em local seco. Absorve umidade e empedra se ficar em piso frio.', 'ok', 'Vai direto no misturador, sem passar pelo moinho. Roda bem em rosca e em chupim.', '{"MISTURADOR","TRANSPORTADOR","CACAMBA_PESAGEM","SUPORTE_BAG"}'::text[], 'informacao', null, '{"Compra farelo em saco ou big bag?","De qual esmagadora/revenda?","Tem espaço coberto e seco pra estocar?"}'::text[], 'O farelo de soja é o músculo da ração — é o que dá proteína. Ele já vem pronto, não precisa moer: entra direto no misturador.', 'Proteína nº 1. Entra direto no misturador, não passa pelo moinho. Empedra se pegar umidade.', 'Abundante no Centro-Oeste e Sul (maiores esmagadoras). Norte e Nordeste dependem de frete.', 'farelo-soja', '🫘', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 50),
  ('caroco-algodao', 'Caroço de algodão (integral)', 'proteico', 'Semente inteira do algodão, com línter, óleo e proteína. Alimento "três em um": energia, proteína e fibra.', '{"caroço de algodão","semente de algodão"}'::text[], 'Fornece ao mesmo tempo proteína, energia (óleo) e fibra efetiva. Valorizado em vaca leiteira.', 'Referência: ~23% de proteína bruta e cerca de 18–20% de óleo.', '{"bovinos": "Referência de até ~15–20% da matéria seca, com limites que variam conforme o volumoso da dieta."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Contém GOSSIPOL — tóxico para monogástricos. NÃO usar em aves e suínos.","Limitar para touros, novilhas e animais jovens (efeito sobre a reprodução).","Excesso de gordura na dieta prejudica a fermentação ruminal."}'::text[], 'Baixa quando bem armazenado.', 'BAIXA — o línter deixa o caroço fofo e volumoso.', 'Semente inteira, coberta de fibra (línter), pegajosa entre si.', 'dificil', true, true, false, true, false, false, true, false, null, true, null, null, false, false, null, 'horizontal', true, 'Barracão coberto. Aquece e mofa se empilhado úmido.', 'ressalva', 'O línter faz o caroço "agarrar" — é o pior ingrediente da lista para fluir. Trava em rosca e chupim, forma ponte em caixa e silo e não escoa por gravidade como grão. Se o cliente usa caroço, o projeto tem que prever isso: misturador HORIZONTAL e alimentação direta, não rosca longa.', '{"MISTURADOR","CAIXA"}'::text[], 'atencao', 'NÃO usar em aves e suínos (gossipol). Não fluidiza: não dimensionar transporte helicoidal longo contando com ele.', '{"É gado de corte, leite ou tem monogástrico junto na propriedade?","Compra caroço com línter ou deslintado?","Como movimenta hoje — pá carregadeira, na mão?","Tem risco de a mesma linha fazer ração de ave ou suíno depois?"}'::text[], 'O caroço é ótimo pro gado: dá proteína, energia e fibra de uma vez. Só que ele não escorre — o línter agarra. E ele não pode ir pra ração de ave nem de porco de jeito nenhum.', 'Três em um pro ruminante. Gossipol: proibido em ave e suíno. Não flui — cuidado no dimensionamento de rosca e caixa.', 'Onde se planta algodão: Centro-Oeste (MT) e Bahia. Muito usado no leite de MG, SP e no semiárido.', 'caroco-algodao', '🫘', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 60),
  ('farelo-algodao', 'Farelo de algodão', 'proteico', 'Torta que sobra da extração do óleo do caroço de algodão, moída. Proteico alternativo ao farelo de soja.', '{"torta de algodão"}'::text[], 'Fonte de proteína vegetal, geralmente mais barata que a soja. Substitui parcialmente o farelo de soja.', 'Referência: 28–40% de proteína bruta, muito variável conforme o processamento.', '{"bovinos": "5–15% do concentrado (referência)", "aves_suinos": "Muito baixo ou zero, por causa do gossipol."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Carrega GOSSIPOL — mesmas restrições do caroço para monogástricos e reprodutores.","Qualidade de proteína inferior à da soja (menos lisina).","Composição varia muito conforme o processamento — análise laboratorial é recomendável."}'::text[], null, '~550–620 kg/m³.', 'Farelo, às vezes com pedaços de casca.', 'media', true, true, false, false, true, false, true, false, 'Pode vir em torta/placa; nesse caso precisa quebrar no moinho.', true, null, null, true, false, null, 'qualquer', false, 'Coberto e seco.', 'ok', 'Farelo já moído entra direto no misturador. Se vier em torta prensada, passa antes pelo moinho de martelo.', '{"MISTURADOR","MOINHO","TRANSPORTADOR"}'::text[], 'atencao', 'Coproduto: composição varia de lote pra lote. Recomendar análise laboratorial antes de fechar fórmula em cima dele.', '{"Vem em farelo ou em torta/placa?","Tem laudo de análise do fornecedor?","A mesma linha vai fazer ração de ave ou suíno?"}'::text[], 'É proteína mais barata que a soja, mas só serve pro ruminante. E, por ser coproduto, cada lote vem diferente — vale pedir análise pro fornecedor.', 'Proteico mais barato que soja, só pra ruminante (gossipol). Coproduto: composição variável, pedir análise.', 'Onde há esmagamento de algodão: MT, BA e agroindústrias do Nordeste e Centro-Oeste.', null, '🫘', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 70),
  ('concentrado-proteico', 'Concentrado proteico', 'proteico', 'Mistura pronta rica em proteína, minerais e vitaminas, feita para o produtor diluir com o grão que já tem na fazenda.', '{"concentrado","concentrado comercial"}'::text[], 'Entrega proteína e balanceamento de forma prática: o produtor mistura com o próprio milho e forma a ração completa, sem comprar cada matéria-prima separada.', 'Varia com o produto comercial. Seguir o rótulo do fabricante.', '{"geral": "Conforme o rótulo do fabricante. Concentrados de 20–40% de proteína costumam entrar a 20–50% da mistura final."}'::jsonb, '{"bovinos","suinos","aves","ovinos","caprinos"}'::text[], '{"Seguir a proporção de mistura do rótulo — é obrigação legal e nutricional.","Menos flexível que formular do zero."}'::text[], null, 'Varia com o produto.', 'Farelado (a maioria) ou peletizado, conforme o fabricante.', 'media', true, false, false, false, true, false, false, false, null, true, null, null, true, null, null, 'qualquer', false, 'Sacaria em local seco, respeitando a validade (tem vitamina).', 'ok', 'É exatamente o caso de uso da fábrica de ração na propriedade: o cliente compra o concentrado e mistura com o milho dele. Muitas vendas da Compacta nascem desse cenário. Se o concentrado vier PELETIZADO, ele entra assim mesmo no misturador — a Branorte não peletiza, mas também não precisa.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'informacao', 'Atenção à validade: concentrado tem vitamina, que degrada com calor e tempo.', '{"Qual concentrado usa hoje e de qual marca?","Qual a proporção do rótulo?","Compra pronto e mistura na mão, ou compra ração completa?","Quantos sacos por mês?"}'::text[], 'Se o senhor já compra concentrado e mistura com o milho na mão ou na enxada, é exatamente aí que a fábrica entra: mesma fórmula, mistura homogênea e no volume que o senhor precisa.', 'Atalho do produtor: proteína + minerais + vitaminas prontos pra misturar com o milho da fazenda. Caso de uso clássico da Compacta.', 'Disponível em todo o país via revendas agropecuárias.', null, '🫘', 'aprovado', true, '{"Foto anterior REPROVADA (era pellet de fabricante concorrente). Precisa de foto do acervo Branorte."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 80),
  ('torta-dende', 'Torta de dendê / palmiste', 'coproduto', 'Coproduto da extração do óleo de dendê ou palmiste. Torta fibrosa com proteína média.', '{"torta de palmiste","farelo de palmiste","dendê"}'::text[], 'Fonte regional de proteína, fibra e energia residual para ruminantes, aproveitando resíduo da agroindústria do dendê.', 'Referência: ~14–18% de proteína bruta, fibra alta, com gordura residual.', '{"bovinos": "Referência de até ~20–30% do concentrado.", "aves_suinos": "Baixo, pela fibra alta."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Fibra alta e presença de casca dura limitam o uso em monogástricos.","Qualidade muito variável conforme a extração — coproduto exige análise.","Gordura residual rancifica."}'::text[], 'Variável. Torta úmida aquece e mofa rápido.', 'Média a baixa.', 'Torta grosseira com fragmentos de casca.', 'media', true, true, true, true, true, false, true, true, 'Fragmentos de casca são duros: desgastam martelo e peneira.', false, null, null, true, true, null, 'horizontal', true, 'Coberto, seco e com giro rápido (a gordura residual rancifica).', 'ressalva', 'Processa, mas os fragmentos de casca são abrasivos e a gordura residual suja o equipamento. Se for uso pesado, conversar sobre peça de reposição e rotina de limpeza.', '{"MOINHO","MISTURADOR","ACESSORIO"}'::text[], 'atencao', 'Coproduto de qualidade muito variável. Análise laboratorial recomendada antes de compor a fórmula.', '{"Tem fornecedor de torta perto ou o frete inviabiliza?","Vem seca ou úmida?","Tem laudo de análise?"}'::text[], 'No Pará e na Bahia a torta de dendê é barata porque é resíduo da usina de óleo. Serve pro gado. Mas cada carga vem diferente e a casca desgasta um pouco mais a máquina.', 'Coproduto regional do Norte/BA para ruminante. Abrasivo e oleoso. Qualidade variável: pedir análise.', 'Norte (PA, principal polo de óleo de palma) e Bahia. Fora dessas regiões o frete inviabiliza.', null, '🫘', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Foto anterior REPROVADA (mostrava frutos frescos, não a torta). Precisa de foto real da torta."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 90),
  ('calcario-calcitico', 'Calcário calcítico', 'mineral', 'Rocha calcária moída, rica em carbonato de cálcio. A fonte mineral mais barata de cálcio.', '{"calcário","carbonato de cálcio"}'::text[], 'Fonte de CÁLCIO. Forma osso e casca de ovo. Em poedeira é o que sustenta a casca firme.', 'Referência: ~34–38% de cálcio. Não contém fósforo.', '{"frango_corte": "~0,8–1,2% da ração", "poedeiras": "8–10% da ração (alta demanda para casca)", "suinos_bovinos": "0,5–2% (referência)"}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Só fornece cálcio — NÃO tem fósforo. Não confundir com fosfato.","Excesso de cálcio atrapalha a absorção de fósforo e de outros minerais.","Calcítico (Ca) é diferente de dolomítico (Ca + Mg)."}'::text[], 'Higroscópico: empedra em ambiente úmido.', 'ALTA — ~1.300–1.500 kg/m³. Muito mais pesado que os farelos.', 'Pó fino a granulado.', 'media', true, true, true, false, true, false, false, false, 'Chega moído. Em poedeira, parte grossa (granulado) é desejável — não moer tudo fino.', true, false, false, true, true, false, 'horizontal', true, 'Local seco e sobre estrado. Empedra em contato com piso frio.', 'ressalva', 'Denso e abrasivo. Por ser muito mais pesado que os farelos, tende a SEGREGAR (descer no misturador) — em produto mineral pesado o misturador HORIZONTAL entrega mistura melhor que o vertical. Gera pó fino: prever exaustão no ponto de carga.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA"}'::text[], 'atencao', 'Material denso: risco de segregação e de erro de dosagem se a balança não tiver resolução adequada. Gera pó fino no ponto de carga.', '{"Vai fazer ração de poedeira? (é onde o calcário entra pesado)","Compra calcário granulado ou pó?","Quem faz a formulação hoje?"}'::text[], 'O calcário é o cálcio — é o que faz a casca do ovo ser firme e o osso ser forte. Ele é bem mais pesado que o farelo, então tem que misturar direito, senão desce tudo pro fundo.', 'Cálcio barato. Não tem fósforo. Denso e abrasivo: risco de segregação — misturador horizontal é o indicado.', 'Abundante e barato no Brasil todo. O custo é quase todo frete.', 'calcario-calcitico', '🧂', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 100),
  ('sal-comum', 'Sal comum (cloreto de sódio)', 'mineral', 'Sal industrial (NaCl) usado na ração e como veículo em suplemento mineral.', '{"sal branco","NaCl","sal grosso"}'::text[], 'Fornece sódio e cloro: equilíbrio eletrolítico, hidratação e apetite. No cocho a pasto, funciona também como REGULADOR de consumo do suplemento.', 'Cloreto de sódio. Pureza varia com a origem.', '{"racao": "0,3–0,5% da ração (referência)", "suplemento_pasto": "Entra como parte da mistura mineral, dosado para regular o consumo."}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Excesso causa sede intensa e pode intoxicar, sobretudo se faltar água.","Água limpa à vontade é obrigatória sempre que há sal na dieta."}'::text[], 'MUITO higroscópico: puxa umidade do ar e empedra.', 'ALTA — ~1.200–1.300 kg/m³.', 'Cristal, de fino a grosso.', 'media', true, true, true, false, true, true, false, false, null, true, null, null, true, false, true, 'horizontal', true, 'Local MUITO seco, sobre estrado, longe de parede. Empedra com facilidade.', 'ressalva', 'CORROSIVO. É o principal agressor do equipamento nesta lista. Quem trabalha com sal e mineral precisa de rotina de limpeza e de não deixar material parado dentro da máquina no fim do dia. Denso: misturador HORIZONTAL é o indicado. NÃO prometer resistência ilimitada da chapa galvanizada — galvanizado retarda a corrosão, não a elimina; para uso pesado e contínuo com sal, avaliar inox com a engenharia.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA"}'::text[], 'atencao', 'CORROSÃO. Não deixar sal acumulado dentro do misturador, da rosca ou da caçamba após o expediente. Limpeza ao fim de cada rodada de produto mineral.', '{"Vai produzir sal mineral/proteinado ou só ração?","Com que frequência — todo dia ou por batelada?","A mesma máquina vai alternar entre mineral e ração?","Tem alguém pra fazer a limpeza no fim do dia?"}'::text[], 'O sal é essencial pro animal, mas ele é agressivo com a máquina. Quem faz mineral tem que limpar o equipamento no fim do dia e não deixar produto parado dentro. Isso não é defeito da máquina — é a natureza do sal.', 'Sódio e cloro; regula consumo no cocho. CORROSIVO e denso: misturador horizontal, limpeza diária, sem promessa de chapa eterna.', 'Produzido no litoral do RN (salinas de Mossoró e Areia Branca). Barato em todo lugar.', 'sal-comum', '🧂', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 110),
  ('sal-mineral', 'Sal mineral (mistura mineral)', 'mineral', 'Mistura pronta de sal comum com macro e microminerais para suplementar animais a pasto.', '{"mistura mineral","suplemento mineral","mineral de cocho"}'::text[], 'Corrige deficiências minerais do pasto brasileiro (naturalmente pobre em fósforo e microminerais). Sustenta fertilidade, ganho de peso, imunidade e desenvolvimento ósseo do gado a campo.', 'Varia com a formulação comercial (Ca, P, Na, Zn, Cu, Mn, Se, Co, I...). O teor de fósforo é o que mais encarece.', '{"bovinos": "Fornecido à vontade no cocho. Consumo alvo de referência ~50–100 g/animal/dia, regulado pelo teor de sal."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Escolher a formulação certa por categoria e por estação (seca x águas).","Há versões com ureia — nesse caso valem TODAS as restrições da ureia.","Cocho coberto e sempre abastecido."}'::text[], 'Higroscópico. Empedra no cocho e no estoque.', 'ALTA — mistura de minerais é pesada.', 'Pó e granulado misturados.', 'dificil', true, true, true, false, true, true, false, false, null, true, true, false, true, true, true, 'horizontal', true, 'Seco, coberto, sobre estrado, com giro rápido.', 'ressalva', 'Produzir mineral na propriedade é um caso de venda real, mas exige projeto pensado: produto DENSO e CORROSIVO, com microminerais em dose pequena. Misturador HORIZONTAL, balança com resolução compatível com as menores inclusões, e rotina de limpeza. Não é o mesmo projeto de quem só tritura milho.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'atencao', 'Produto denso e corrosivo, com microingredientes. Erro de homogeneização entrega mineral desbalanceado ao rebanho inteiro. Formulação por profissional habilitado.', '{"Ele compra mineral pronto ou pensa em produzir?","Quantas cabeças e qual o consumo mensal de mineral hoje?","É mineral puro, proteinado, ou tem ureia?","Quem faz a formulação?","Vai alternar com ração na mesma máquina?"}'::text[], 'Dá pra produzir o mineral aqui na propriedade, sim — mas é um projeto diferente do de moer milho. Mineral é pesado, é corrosivo e tem ingrediente que entra em grama. Precisa do misturador certo e da balança certa.', 'Suplemento de pasto. Denso, corrosivo, com microingredientes. Projeto específico: horizontal + balança fina + limpeza.', 'Todo o Brasil; demanda enorme na pecuária extensiva (Centro-Oeste, Norte, Nordeste) por causa de solos pobres em fósforo.', null, '🧂', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Densidade, abrasividade, formação de ponte e misturador indicado precisam do aval da engenharia Branorte (hoje são inferência de literatura e prática, não medição)."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 120),
  ('fosfato-bicalcico', 'Fosfato bicálcico', 'mineral', 'Sal mineral inorgânico de cálcio e fósforo, de alta disponibilidade.', '{"bicálcico","fosfato","DCP"}'::text[], 'Principal fonte de FÓSFORO (e também de cálcio). Fósforo é chave para osso, energia celular, fertilidade e metabolismo ruminal. Corrige a deficiência típica do gado a pasto.', 'Referência: ~23% de fósforo e ~24–30% de cálcio.', '{"aves_suinos": "1–2% da ração (referência)", "sal_mineral_bovinos": "30–50% da mistura (referência)", "bovinos_confinados": "0,5–1,5% (referência)"}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"É o mineral mais caro da fórmula — dosar com precisão.","Manter a relação cálcio:fósforo equilibrada.","Atenção ao teor de FLÚOR: fosfatos mal desflorados são tóxicos por acúmulo.","Diferente do calcário, que só tem cálcio."}'::text[], 'Higroscópico, empedra.', 'MUITO ALTA — ~1.400–1.700 kg/m³. O mais denso da lista.', 'Pó fino a granulado.', 'media', true, true, true, false, true, true, false, false, null, true, false, false, true, true, true, 'horizontal', true, 'Seco, sobre estrado. Empedra com facilidade.', 'ressalva', 'O ingrediente mais DENSO da lista — segrega com facilidade num misturador vertical. Denso + caro = exige balança com boa resolução, senão o erro de dosagem sai caro em dinheiro E em nutrição. Misturador horizontal indicado.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA"}'::text[], 'atencao', 'Muito denso e caro. Erro de dosagem custa dinheiro e desbalanceia a relação Ca:P. Verificar teor de flúor com o fornecedor.', '{"Compra fosfato hoje? De qual fornecedor?","Tem laudo com teor de fósforo e de flúor?","Que balança usa pra pesar os minerais?"}'::text[], 'O fosfato é o fósforo, e é o mineral mais caro da fórmula. Como ele é muito pesado, a mistura tem que ser boa e a balança tem que ser precisa — errar aqui é errar dinheiro.', 'Fósforo de alta absorção, o mineral mais caro e mais denso. Pede balança precisa e misturador horizontal.', 'Fabricado industrialmente (jazidas em MG e GO). Vendido no país todo; peso e frete pesam no custo.', null, '🧂', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 130),
  ('nucleo-premix', 'Núcleo / Premix', 'nucleo_premix', 'Mistura concentrada de vitaminas, microminerais, aminoácidos e aditivos. É o que "fecha" o balanceamento da ração.', '{"núcleo","premix","suplemento vitamínico mineral"}'::text[], 'Fecha as lacunas que milho e soja não suprem: vitaminas, microminerais (zinco, cobre, selênio), aminoácidos e aditivos.', 'Varia por produto e por fase. Seguir o rótulo.', '{"geral": "Tipicamente 0,5–4% da ração (dose pequena, alto valor agregado). Seguir o rótulo do fabricante."}'::jsonb, '{"aves","suinos","bovinos","ovinos","caprinos"}'::text[], '{"Respeitar dose e FASE (inicial, crescimento, terminação, postura).","Vitaminas degradam com calor e tempo: atenção à validade e ao armazenamento."}'::text[], 'Sensível. Guardar fechado.', 'Variável conforme o veículo.', 'Pó fino.', 'media', true, false, false, false, true, false, false, false, null, false, true, true, true, true, null, 'qualquer', true, 'Fechado, ao abrigo de luz e calor, com controle de validade.', 'ressalva', 'MICROINGREDIENTE: entra em quantidade pequena numa massa grande. Jogar direto no misturador não homogeneíza. O correto é PRÉ-MISTURA — diluir o núcleo numa parte do farelo antes de mandar pro misturador principal. E a balança precisa ter resolução pra pesar a menor inclusão da fórmula, não só a maior.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA"}'::text[], 'atencao', 'Erro de dosagem de núcleo desbalanceia a ração inteira. Fazer PRÉ-MISTURA. Conferir se a balança pesa a menor inclusão com precisão.', '{"Qual núcleo usa e de qual fabricante?","Qual a inclusão por tonelada?","Como pesa hoje — balança de cozinha, balança de saco?","Faz pré-mistura ou joga direto?","Usa fórmula diferente por fase?"}'::text[], 'O núcleo é pouquinho mas é o que faz a ração ser ração. Como entra pouco, não adianta jogar por cima: tem que misturar primeiro com uma parte do farelo, senão um saco sai forte e o outro sai fraco.', 'Vitaminas e microminerais que fecham a fórmula. Microingrediente: exige pré-mistura e balança com boa resolução.', 'Vendido em todo o Brasil pelas indústrias de nutrição. Não depende de safra.', null, '💊', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 140),
  ('ureia', 'Ureia pecuária', 'risco', 'Nitrogênio não-proteico (NNP) usado para baratear a proteína de ruminantes. É o ingrediente de maior risco desta lista.', '{"ureia","NNP","nitrogênio não proteico"}'::text[], 'Fornece nitrogênio para os micro-organismos do rúmen fabricarem proteína microbiana. Substitui parte do farelo proteico a custo muito menor.', 'Referência: ~45% de nitrogênio. Costuma-se citar o equivalente proteico multiplicando por 6,25 — é uma CONVERSÃO de cálculo, não proteína verdadeira, e não se aplica a monogástrico.', '{"ruminantes_adaptados": "Referência de no máximo ~1% da matéria seca total ingerida (ou ~3% do concentrado), em animal TOTALMENTE adaptado. Faixa a confirmar com o nutricionista, caso a caso."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"SOMENTE ruminantes ADULTOS com rúmen funcional.","NUNCA para aves, suínos e equinos.","NUNCA para animal jovem, com rúmen ainda não desenvolvido.","NUNCA fornecer a animal em jejum.","Exige adaptação gradual e água à vontade."}'::text[], 'MUITO higroscópica: puxa água do ar, empedra e vira melado.', '~750–800 kg/m³.', 'Grânulo branco (perolada) ou pó.', 'media', true, true, false, false, true, true, false, false, null, false, true, true, true, true, true, 'horizontal', true, 'Fechado e MUITO seco, separado dos demais insumos e identificado.', 'ressalva', 'Mecanicamente a máquina mistura. O problema não é mecânico, é de CONSEQUÊNCIA: mistura mal feita concentra ureia num ponto da massa e mata animal. Se o cliente vai usar ureia, o projeto precisa de misturador com boa homogeneização (horizontal), pré-mistura e balança precisa — e ele precisa de acompanhamento profissional. Vender a máquina não é vender a fórmula.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA"}'::text[], 'alto_risco', 'ALTO RISCO — INTOXICAÇÃO POR AMÔNIA, PODE MATAR O ANIMAL. Utilizar somente com formulação e acompanhamento de profissional habilitado. Erros de dosagem ou de homogeneização podem causar intoxicação. Exige adaptação gradual, água à vontade e jamais fornecimento a animal em jejum, jovem ou monogástrico. O vendedor NÃO fornece receita, dose nem protocolo de adaptação.', '{"O cliente já usa ureia hoje? Com acompanhamento de quem?","Tem nutricionista ou técnico responsável pela formulação?","A mesma linha vai fazer ração de ave ou suíno depois? (contaminação cruzada)","Como é feita a pesagem hoje?"}'::text[], 'A ureia baixa muito o custo da proteína do gado, mas ela é perigosa: se a mistura não ficar homogênea, o animal pode se intoxicar. Por isso ela exige acompanhamento de um profissional. Eu vendo o equipamento que mistura bem — a fórmula e a dose são com o técnico do senhor.', 'Proteína barata pro ruminante adulto. ALTO RISCO: mistura mal feita mata. Só com profissional habilitado. Nunca em ave, suíno ou animal jovem.', 'Fabricada industrialmente. Muito usada na pecuária extensiva do Centro-Oeste, Norte e semiárido.', 'ureia', '☠️', 'aprovado', true, '{"Dose e protocolo de adaptação NÃO devem constar do guia. São responsabilidade do profissional que formula."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 150),
  ('farelo-trigo', 'Farelo de trigo', 'fibroso', 'Coproduto da moagem do trigo — o farelo que sobra da produção de farinha branca.', '{"farelo de trigo","farelinho"}'::text[], 'Fibra moderada com energia e proteína médias. Dá volume, ajuda o trânsito intestinal e é muito usado por palatabilidade. Fonte relevante de fósforo (embora pouco disponível para monogástrico).', 'Referência: ~15% de proteína bruta. Fósforo majoritariamente na forma de fitato.', '{"suinos_matrizes": "10–25% (referência)", "bovinos": "5–20% do concentrado", "aves": "até ~5–10%, limitado pela fibra"}'::jsonb, '{"suinos","bovinos","aves","ovinos","caprinos"}'::text[], '{"Fibra alta limita o uso em frango de corte e em leitão (dilui a energia).","Fósforo em forma de fitato, pouco aproveitado sem enzima fitase."}'::text[], 'Absorve umidade com facilidade — emboloramento é o defeito comum.', 'BAIXA — ~250–350 kg/m³. É o mais "fofo" da lista.', 'Farelo leve e volumoso.', 'media', true, true, false, false, true, false, true, false, null, true, null, null, true, true, null, 'qualquer', false, 'Seco e ventilado, com giro. Absorve umidade e mofa.', 'ok', 'Entra direto no misturador. ATENÇÃO AO VOLUME: por ser muito leve, ocupa muito espaço por quilo — uma fórmula com bastante farelo de trigo enche o misturador antes de bater o peso. Dimensionar o misturador pelo VOLUME da fórmula, não só pela capacidade em quilos.', '{"MISTURADOR","TRANSPORTADOR","SUPORTE_BAG"}'::text[], 'informacao', 'Baixa densidade: a capacidade real do misturador em quilos cai quando a fórmula tem muito farelo de trigo.', '{"Usa farelo de trigo na fórmula? Em que percentual?","Compra de moinho da região?","A fórmula tem muito ingrediente leve? (isso muda o tamanho do misturador)"}'::text[], 'O farelo de trigo é leve e fofo. Se a fórmula do senhor tem bastante farelo, o misturador enche de volume antes de encher de peso — por isso a gente olha o volume da fórmula na hora de escolher o tamanho.', 'Fibra moderada e palatável. MUITO leve: dimensionar o misturador por volume, não só por peso.', 'Maior oferta no Sul (PR, RS) e onde há moinho de trigo.', 'farelo-trigo', '🌾', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 160),
  ('silagem-volumoso', 'Silagem e volumosos', 'fibroso', 'Forragem picada e fermentada (milho, sorgo, capim, cana), ou volumoso fresco e feno. Base da dieta do ruminante — e ingrediente ÚMIDO.', '{"silagem","silagem de milho","volumoso","cana picada","capim picado"}'::text[], 'Fibra e volume que fazem o rúmen funcionar (ruminação, salivação, pH). Silagem de milho e de sorgo também traz energia do grão. É a comida de base do gado; o concentrado é o complemento.', 'Muito variável com a cultura, o ponto de corte e a fermentação. Alta umidade.', '{"ruminantes": "40–100% da matéria seca da dieta, conforme o sistema."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Fibra é ESSENCIAL para o ruminante — dieta sem volumoso causa acidose.","Silagem mal compactada ou mal vedada estraga: mofo, perda e micotoxinas.","Não serve para monogástricos."}'::text[], 'ALTA — geralmente 60–70% de água. É a característica que define tudo aqui.', 'Alta na massa compactada, mas com muita água.', 'Material picado e úmido.', 'nao_flui', false, true, false, false, false, false, true, false, null, false, null, null, false, false, true, 'nenhum', true, 'Silo trincheira, bolsa ou superfície, bem compactado e vedado.', 'incompativel', 'A fábrica Branorte é de RAÇÃO FARELADA — produto SECO. Silagem e volumosos úmidos NÃO entram: não fluem por gravidade, empastam a rosca e o helicoide, não homogeneízam num misturador de ração e deixam resíduo úmido que apodrece dentro do equipamento. Misturar dieta completa (TMR) com volumoso é trabalho de VAGÃO MISTURADOR, que é outro equipamento e outro processo. Diferenciar sempre: a Branorte faz a MISTURA SECA (o concentrado); o volumoso entra depois, no cocho ou no vagão.', '{}'::text[], 'incompativel', 'NÃO tratar como ingrediente comum de fábrica de ração farelada. Separar mistura seca (concentrado) de dieta total (TMR). Se o cliente quer misturar volumoso, o equipamento é outro.', '{"Ele faz silagem própria?","Quer misturar TUDO junto (dieta completa) ou só o concentrado?","Como entrega o volumoso hoje — vagão, cocho, na pá?","Se ele quer TMR, isso é vagão misturador — a nossa fábrica faz a parte seca."}'::text[], 'A silagem é a base do gado, mas ela é molhada. A nossa fábrica faz a mistura seca — o concentrado. A silagem o senhor continua entregando no cocho ou no vagão. São dois trabalhos diferentes, e é melhor eu deixar isso claro agora do que o senhor descobrir depois.', 'Base do ruminante, mas ÚMIDO: não entra na fábrica farelada. TMR é vagão misturador. A Branorte faz a parte seca.', 'Produzida na própria fazenda no país todo. Silagem de milho domina Sul, Sudeste e Centro-Oeste; cana e capim são fortes no Nordeste.', 'silagem-milho', '🌾', 'aprovado', true, '{"Confirmar com a engenharia se há qualquer configuração Branorte que aceite úmidos (hoje o motor de /producao-propria bloqueia por padrão)."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 170),
  ('palma-forrageira', 'Palma forrageira', 'fibroso', 'Cacto cultivado como forragem no semiárido. Muito rico em água e energia; ingrediente ÚMIDO.', '{"palma","palma miúda","palma gigante","Opuntia","Nopalea"}'::text[], 'Fonte de ENERGIA e ÁGUA no semiárido. Reserva estratégica de seca: mantém o animal hidratado e com energia quando o pasto some.', 'Muito rica em água e em carboidratos. Muito pobre em proteína e em fibra efetiva.', '{"ruminantes": "Referência de 30–60% da matéria seca, sempre associada a fonte de fibra longa e a fonte proteica."}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{"Muito pobre em fibra efetiva e em proteína — sozinha causa diarreia e não sustenta o rúmen.","Precisa ser combinada com feno ou silagem (fibra) e com fonte proteica."}'::text[], 'MUITO ALTA — em torno de 90% de água.', 'Alta em massa, mas quase tudo é água.', 'Raquete picada, úmida e pegajosa.', 'nao_flui', false, true, false, false, false, false, false, false, null, false, null, null, false, null, true, 'nenhum', true, 'Fornecida fresca, picada na hora. Não estoca.', 'incompativel', 'Volumoso de altíssima umidade — mesma regra da silagem. Não entra na fábrica de ração farelada. Picar palma é trabalho de forrageira/picadeira, não da linha Compacta.', '{}'::text[], 'incompativel', 'Ingrediente úmido: fora do escopo da fábrica farelada. Não prometer processamento na linha Compacta.', '{"Ele tem palma plantada?","Como pica hoje?","A ração que ele quer produzir é o CONCENTRADO que acompanha a palma?"}'::text[], 'A palma salva o rebanho na seca, mas ela é praticamente água — não vai na fábrica de ração. O que a nossa fábrica faz é o concentrado que acompanha a palma, que é justamente a proteína que falta nela.', 'Energia e água na seca do semiárido. ÚMIDA: fora da fábrica farelada. A Branorte faz o concentrado que a acompanha.', 'Típica do Nordeste e do semiárido (PE, PB, BA, AL, RN, CE).', 'palma-forrageira', '🌵', 'aprovado', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 180),
  ('casquinha-soja', 'Casquinha de soja', 'fibroso', 'Casca da soja moída, coproduto do esmagamento. Fibra muito digestível.', '{"casca de soja"}'::text[], 'Fibra digestível que substitui parte do volumoso sem acidificar o rúmen. Muito usada em confinamento e em vaca leiteira.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], null, 'MUITO BAIXA — é o ingrediente mais leve e volumoso da lista.', 'Farelo leve e fofo (às vezes peletizado pra facilitar transporte).', 'dificil', null, true, null, null, true, null, null, false, null, true, null, null, true, true, null, 'qualquer', false, null, 'ressalva', 'Entra direto, mas é MUITO leve: enche o misturador de volume sem bater o peso e forma ponte em caixa e silo. Dimensionar pelo volume.', '{"MISTURADOR","SUPORTE_BAG"}'::text[], 'atencao', 'Densidade baixíssima: derruba a capacidade útil do misturador em quilos.', '{"Usa casquinha? Vem solta ou peletizada?"}'::text[], null, 'Fibra digestível pro ruminante. Leveza extrema: dimensionar misturador por volume.', 'Onde há esmagamento de soja: Centro-Oeste e Sul.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 190),
  ('ddg-ddgs', 'DDG / DDGS (grãos secos de destilaria)', 'coproduto', 'Coproduto da produção de etanol de milho. Proteico e energético, em expansão no Centro-Oeste.', '{"DDGS","DDG","grãos de destilaria"}'::text[], 'Fonte de proteína e energia. Cresceu muito com as usinas de etanol de milho em MT e GO.', null, '{}'::jsonb, '{"bovinos","suinos","aves"}'::text[], '{"Composição varia MUITO entre usinas e entre lotes — análise laboratorial é essencial.","Teor de gordura variável, o que muda o limite de inclusão."}'::text[], null, 'Média a baixa.', 'Farelo grosso, levemente oleoso.', 'media', true, true, null, true, true, null, true, false, null, true, null, null, true, null, null, 'qualquer', false, null, 'ok', 'Entra direto no misturador. Se vier úmido (WDG), aí NÃO entra — só a versão SECA (DDGS).', '{"MISTURADOR","TRANSPORTADOR"}'::text[], 'atencao', 'Só a versão SECA. Grão de destilaria ÚMIDO (WDG) é ingrediente úmido e não entra na fábrica farelada. Coproduto: pedir análise.', '{"É DDGS seco ou úmido?","De qual usina?","Tem laudo?"}'::text[], null, 'Proteína/energia de usina de etanol de milho. Só a versão SECA. Composição variável: pedir análise.', 'Centro-Oeste (MT, GO), acompanhando as usinas de etanol de milho.', null, '🫘', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 200),
  ('farelo-arroz', 'Farelo de arroz', 'energetico', 'Coproduto do beneficiamento do arroz. Energético com gordura, muito usado no Sul.', '{"farelo de arroz integral","farelo de arroz desengordurado"}'::text[], 'Energia com alguma proteína. O integral tem óleo; o desengordurado, não.', null, '{}'::jsonb, '{"bovinos","suinos","aves"}'::text[], '{"O integral RANCIFICA rápido por causa do óleo — giro de estoque curto."}'::text[], null, 'Baixa a média.', 'Farelo fino, oleoso no integral.', 'media', true, null, null, true, true, null, true, false, null, true, null, null, true, true, null, 'qualquer', null, null, 'ok', 'Entra direto. O integral deixa película oleosa no equipamento com o tempo — vale limpeza periódica.', '{"MISTURADOR"}'::text[], 'atencao', 'Integral rancifica: estoque curto e atenção ao cheiro.', '{"É integral ou desengordurado?","Quanto tempo fica estocado?"}'::text[], null, 'Energia regional do Sul. Integral rancifica: giro rápido.', 'Sul (RS, SC) e onde há engenho de arroz.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 210),
  ('quirera-arroz', 'Quirera de arroz', 'energetico', 'Grão de arroz quebrado no beneficiamento. Energético de alta digestibilidade.', '{"arroz quebrado","quirera"}'::text[], 'Amido muito digestível. Boa opção para leitão e para ave em fase inicial.', null, '{}'::jsonb, '{"suinos","aves","bovinos"}'::text[], '{}'::text[], null, '~750–800 kg/m³.', 'Grão quebrado, pequeno.', 'livre', null, null, null, null, true, null, null, true, 'Já vem pequena; pode precisar só de refino.', false, null, null, true, null, null, 'qualquer', null, null, 'ok', 'Comporta-se como grão pequeno. Roda bem no moinho e na rosca.', '{"MOINHO","MISTURADOR","TRANSPORTADOR"}'::text[], 'informacao', null, '{"Tem engenho de arroz na região?"}'::text[], null, 'Amido muito digestível, boa pra leitão e pinto. Comporta-se como grão pequeno.', 'Sul e regiões com engenho de arroz.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 220),
  ('polpa-citrica', 'Polpa cítrica', 'fibroso', 'Coproduto da indústria de suco de laranja, peletizado. Fibra digestível e energia.', '{"polpa cítrica peletizada","bagaço de laranja"}'::text[], 'Fibra altamente digestível para ruminantes, sem o risco de acidose do amido.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], null, 'Média (vem peletizada).', 'Pellet firme.', 'livre', true, null, null, null, null, null, null, true, 'Vem em pellet: precisa quebrar no moinho pra entrar em ração farelada.', false, null, null, true, null, null, 'qualquer', null, null, 'ok', 'Chega peletizada e precisa passar pelo moinho de martelo pra virar farelo. Isso é normal e a linha faz.', '{"MOINHO","MISTURADOR"}'::text[], 'informacao', null, '{"Vem peletizada?","Tem fornecedor perto ou o frete pesa?"}'::text[], null, 'Fibra digestível sem acidose. Vem em pellet: passa pelo moinho antes.', 'São Paulo e Triângulo Mineiro (cinturão citrícola).', null, '🍊', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 230),
  ('farelo-girassol', 'Farelo de girassol', 'proteico', 'Coproduto da extração do óleo de girassol. Proteico com fibra.', '{}'::text[], 'Proteína vegetal alternativa, com fibra mais alta que a soja.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos","aves"}'::text[], '{"Fibra alta limita o uso em monogástrico.","Menos lisina que a soja."}'::text[], null, 'Baixa.', 'Farelo com casca.', 'media', null, null, null, null, true, null, null, false, null, true, null, null, true, null, null, 'qualquer', null, null, 'ok', 'Entra direto no misturador.', '{"MISTURADOR"}'::text[], 'informacao', null, '{}'::text[], null, 'Proteico alternativo com mais fibra que a soja. Entra direto.', 'Centro-Oeste e onde há esmagamento de girassol.', null, '🫘', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 240),
  ('milheto', 'Milheto (grão)', 'energetico', 'Grão energético rústico, tolerante à seca. Alternativa regional ao milho.', '{}'::text[], 'Energia (amido), com proteína um pouco maior que a do milho.', null, '{}'::jsonb, '{"bovinos","aves","suinos","ovinos","caprinos"}'::text[], '{}'::text[], null, '~700 kg/m³.', 'Grão muito pequeno.', 'livre', null, null, null, null, true, null, null, true, 'Grão miúdo: exige peneira fina, senão passa inteiro.', false, null, null, true, null, null, 'qualquer', null, null, 'ok', 'Roda bem, mas o grão é miúdo — conferir a peneira do moinho pra não passar inteiro.', '{"MOINHO","MISTURADOR","ACESSORIO"}'::text[], 'informacao', null, '{"Planta milheto na propriedade?"}'::text[], null, 'Energia rústica de seca. Grão miúdo: peneira fina no moinho.', 'Centro-Oeste e Nordeste, muito usado em safrinha e cobertura.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 250),
  ('feno', 'Feno', 'fibroso', 'Forragem cortada e desidratada (capim, alfafa, leguminosas). Volumoso SECO.', '{}'::text[], 'Fibra longa efetiva para o rúmen, conservada seca.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], 'Baixa (é seco) — mas continua sendo FIBRA LONGA.', 'MUITO baixa.', 'Fibra longa, em fardo ou picada.', 'nao_flui', null, true, null, null, null, null, null, true, 'Fibra longa não entra em ração farelada sem moagem; e mesmo moída, enrola no helicoide.', false, null, null, false, null, null, 'nenhum', true, null, 'incompativel', 'Apesar de SECO, o feno é fibra LONGA: enrola no helicoide, não flui e não homogeneíza em misturador de ração. Feno é trabalho de forrageira/picadeira e de vagão misturador, não da linha Compacta.', '{}'::text[], 'incompativel', 'Seco não quer dizer compatível. Fibra longa trava o helicoide.', '{"Ele quer misturar feno na ração ou fornecer separado no cocho?"}'::text[], null, 'Volumoso SECO, mas fibra longa: enrola no helicoide. Fora da fábrica farelada.', 'Todo o Brasil.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 260),
  ('casca-algodao', 'Casca de algodão', 'fibroso', 'Casca do caroço de algodão. Fibra efetiva barata para ruminantes.', '{}'::text[], 'Fibra efetiva de baixo custo, usada pra dar "coçadura" ao rúmen em dieta de alto grão.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], null, 'MUITO baixa.', 'Casca leve e volumosa.', 'dificil', null, true, null, null, true, null, null, false, null, true, null, null, false, true, null, 'horizontal', true, null, 'ressalva', 'Muito leve e mal fluente: forma ponte e não escoa por gravidade. Se entrar na fórmula, o projeto precisa de alimentação direta no misturador, não de rosca longa.', '{"MISTURADOR"}'::text[], 'atencao', 'Não flui. Não dimensionar transporte helicoidal longo contando com ela.', '{}'::text[], null, 'Fibra efetiva barata. Não flui: alimentação direta, misturador horizontal.', 'MT e BA, junto com o caroço.', null, '🌾', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 270),
  ('melaco', 'Melaço de cana', 'liquido', 'Subproduto da produção de açúcar. Xarope energético e palatabilizante. Ingrediente LÍQUIDO.', '{"melaço","mel final"}'::text[], 'Energia rápida e palatabilidade. Reduz poeira e ajuda a "colar" o pó da mistura.', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], 'Líquido viscoso.', '~1.400 kg/m³ (denso).', 'Xarope viscoso, mais grosso a frio.', 'nao_flui', null, null, null, true, null, null, null, null, null, false, true, null, false, null, true, 'horizontal', true, null, 'incompativel', 'LÍQUIDO viscoso. A linha Compacta padrão não tem sistema de dosagem e aspersão. Melaço adere a tudo, cria crosta e exige limpeza pesada. Não prometer sem avaliação da engenharia.', '{}'::text[], 'incompativel', 'Líquido viscoso: adere, cria crosta e endurece dentro do equipamento. Fora do escopo padrão.', '{"Ele usa melaço hoje? Como adiciona?"}'::text[], null, 'Energia e palatabilidade, mas LÍQUIDO e grudento. Fora do escopo da Compacta padrão.', 'Regiões canavieiras: SP, Nordeste, Centro-Oeste.', null, '🍯', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 280),
  ('bicarbonato-sodio', 'Bicarbonato de sódio', 'mineral', 'Tamponante de rúmen. Usado em dieta de alto grão para conter a acidose.', '{"bicarbonato"}'::text[], 'Tampona o pH do rúmen em dietas de alto concentrado (confinamento, vaca de alta produção).', null, '{}'::jsonb, '{"bovinos","ovinos","caprinos"}'::text[], '{}'::text[], 'Higroscópico.', '~1.000–1.200 kg/m³.', 'Pó fino branco.', 'media', true, null, null, null, true, true, null, false, null, true, true, true, true, true, true, 'horizontal', true, null, 'ressalva', 'Entra em dose pequena: pré-mistura e balança precisa. Sal de sódio — mesma preocupação de corrosão do sal comum.', '{"MISTURADOR","BALANCA"}'::text[], 'atencao', 'Microingrediente e corrosivo. Pré-mistura obrigatória.', '{}'::text[], null, 'Tampona o rúmen em dieta de alto grão. Microingrediente e corrosivo.', 'Industrial, disponível no país todo.', null, '🧂', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 290),
  ('lisina', 'Lisina (aminoácido industrial)', 'aditivo', 'Aminoácido sintético. Permite reduzir farelo de soja mantendo o desempenho.', '{"L-lisina","lisina HCl"}'::text[], 'Primeiro aminoácido limitante em suínos e aves. Substitui parte da proteína bruta da soja, barateando a fórmula.', null, '{}'::jsonb, '{"suinos","aves"}'::text[], '{}'::text[], 'Higroscópico.', 'Média.', 'Pó ou grânulo fino.', 'media', true, null, null, null, true, null, null, false, null, false, true, true, true, true, null, 'qualquer', true, null, 'ressalva', 'MICROINGREDIENTE puro: entra em quilos por tonelada. Sem pré-mistura e sem balança precisa, não homogeneíza.', '{"MISTURADOR","BALANCA"}'::text[], 'atencao', 'Dose pequena e alto impacto. Pré-mistura obrigatória, balança com resolução compatível.', '{"Usa aminoácido industrial na fórmula?","Como pesa hoje?"}'::text[], null, 'Aminoácido que reduz a soja da fórmula. Microingrediente: pré-mistura e balança fina.', 'Industrial, disponível no país todo.', null, '💊', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 300),
  ('metionina', 'Metionina (aminoácido industrial)', 'aditivo', 'Aminoácido sintético. Primeiro limitante em aves.', '{"DL-metionina"}'::text[], 'Primeiro aminoácido limitante em aves (empenamento, postura, conversão).', null, '{}'::jsonb, '{"aves","suinos"}'::text[], '{}'::text[], null, null, 'Pó fino.', 'media', null, null, null, null, true, null, null, false, null, false, true, true, true, true, null, 'qualquer', true, null, 'ressalva', 'Mesmo caso da lisina: microingrediente, exige pré-mistura e balança precisa.', '{"MISTURADOR","BALANCA"}'::text[], 'atencao', 'Microingrediente. Pré-mistura obrigatória.', '{}'::text[], null, 'Aminoácido limitante em aves. Microingrediente: pré-mistura e balança fina.', 'Industrial.', null, '💊', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 310),
  ('fitase-enzimas', 'Fitase e outras enzimas', 'aditivo', 'Enzimas que liberam nutrientes indisponíveis (a fitase libera o fósforo do fitato).', '{"fitase","enzima","complexo enzimático"}'::text[], 'A fitase libera o fósforo preso no fitato dos vegetais, reduzindo a necessidade de fosfato — que é o mineral mais caro.', null, '{}'::jsonb, '{"aves","suinos"}'::text[], '{"Enzima é sensível a CALOR: um dos motivos de a peletização exigir cuidado extra. Em ração farelada esse risco é menor."}'::text[], null, null, 'Pó fino ou líquido, conforme o produto.', 'media', null, null, null, null, true, null, null, false, null, false, true, true, true, null, null, 'qualquer', true, null, 'ressalva', 'Microingrediente com pré-mistura. VANTAGEM DA FARELADA: como não passa por calor de peletização, a enzima sofre menos.', '{"MISTURADOR","BALANCA"}'::text[], 'atencao', 'Microingrediente sensível a calor e a validade. Pré-mistura obrigatória.', '{}'::text[], null, 'Libera fósforo do fitato e economiza fosfato. Microingrediente sensível a calor.', 'Industrial.', null, '💊', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 320),
  ('adsorvente-micotoxinas', 'Adsorvente de micotoxinas', 'aditivo', 'Aditivo que sequestra micotoxinas do alimento, reduzindo o efeito sobre o animal.', '{"sequestrante","anti-micotoxina","adsorvente"}'::text[], 'Reduz o efeito de micotoxinas presentes em grãos contaminados. NÃO limpa o alimento: reduz o dano.', null, '{}'::jsonb, '{"aves","suinos","bovinos"}'::text[], '{"Adsorvente NÃO corrige grão estragado. Milho embolorado continua sendo milho embolorado."}'::text[], null, null, 'Pó fino (argila, parede celular de levedura).', 'media', null, null, true, null, true, null, null, false, null, false, true, true, true, true, null, 'qualquer', true, null, 'ressalva', 'Microingrediente com pré-mistura. Os de base argila são levemente abrasivos.', '{"MISTURADOR","BALANCA"}'::text[], 'atencao', 'Não substitui armazenagem correta. É redução de dano, não solução.', '{"Já teve problema de micotoxina?","Como armazena o milho?"}'::text[], null, 'Reduz o dano da micotoxina — não corrige grão estragado. Microingrediente.', 'Industrial.', null, '💊', 'em_revisao', true, '{"Faixa de inclusão e composição precisam de validação de nutricionista antes de virarem número fechado.","Ingrediente NOVO: aguarda aprovação técnica para ficar visível ao vendedor."}'::text[], '{"rostagno-tabelas"}'::text[], 'Auditoria 2026-08-03', null, null, null, 330)
