-- ============================================================================
-- Guia do Vendedor — seed de MATÉRIAS-PRIMAS
--
-- 18 migradas do guia.html (corrigidas) + 16 novas.
--
-- Correções estruturais em relação ao guia antigo:
--   • FICHA MECÂNICA (moagem, densidade, fluidez, ponte, poeira, corrosão,
--     pré-mistura, misturador indicado) — não existia NENHUMA.
--   • compat_branorte explícito: silagem, palma, óleo, melaço e feno passam a
--     ser 'incompativel' com a linha farelada, alinhando o guia ao motor de
--     /producao-propria, que já os bloqueava. Os dois módulos se contradiziam.
--   • nivel_risco em escala. Ureia sobe para 'alto_risco'; antes usava a mesma
--     tarja amarela de "farelo de trigo absorve umidade".
--   • Faixas de inclusão marcadas como REFERÊNCIA + pendente_validacao.
--
-- Os 16 novos entram como 'em_revisao' — invisíveis ao vendedor até a
-- aprovação do nutricionista, conforme a regra do próprio brief.
-- ============================================================================

on conflict (slug) do update set nome = excluded.nome, categoria = excluded.categoria, resumo = excluded.resumo, sinonimos = excluded.sinonimos, funcao = excluded.funcao, composicao = excluded.composicao, inclusao = excluded.inclusao, especies = excluded.especies, restricoes = excluded.restricoes, umidade = excluded.umidade, densidade_kg_m3 = excluded.densidade_kg_m3, forma_fisica = excluded.forma_fisica, fluidez = excluded.fluidez, empedra = excluded.empedra, forma_ponte = excluded.forma_ponte, abrasivo = excluded.abrasivo, oleoso = excluded.oleoso, gera_poeira = excluded.gera_poeira, corrosivo = excluded.corrosivo, risco_micotoxina = excluded.risco_micotoxina, precisa_moer = excluded.precisa_moer, granulometria = excluded.granulometria, direto_misturador = excluded.direto_misturador, exige_pre_mistura = excluded.exige_pre_mistura, microingrediente = excluded.microingrediente, compat_rosca = excluded.compat_rosca, exige_exaustao = excluded.exige_exaustao, exige_limpeza_rapida = excluded.exige_limpeza_rapida, misturador_indicado = excluded.misturador_indicado, afeta_homogeneidade = excluded.afeta_homogeneidade, armazenamento = excluded.armazenamento, compat_branorte = excluded.compat_branorte, compat_motivo = excluded.compat_motivo, equipamentos = excluded.equipamentos, nivel_risco = excluded.nivel_risco, alerta = excluded.alerta, perguntas = excluded.perguntas, explicar_cliente = excluded.explicar_cliente, resumo_30s = excluded.resumo_30s, regiao = excluded.regiao, imagem_slug = excluded.imagem_slug, emoji = excluded.emoji, status = excluded.status, pendente_validacao = excluded.pendente_validacao, pendencias = excluded.pendencias, fontes = excluded.fontes, autor = excluded.autor, revisor_tecnico = excluded.revisor_tecnico, revisado_em = excluded.revisado_em, proxima_revisao = excluded.proxima_revisao, ordem = excluded.ordem;
